import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Header from './components/Header';
import Footer from './components/Footer';
import SearchForm from './components/SearchForm';
import PropertyList from './components/PropertyList';
import PropertyDetail from './components/PropertyDetail';
import FavouritesList from './components/FavouritesList';
import { useFavourites } from './hooks/useFavourites';
import './styles/main.css';

function App() {
  const [properties, setProperties] = useState([]);
  const [filteredProperties, setFilteredProperties] = useState([]);
  const [searchCriteria, setSearchCriteria] = useState({});
  const { favourites, addFavourite, removeFavourite, clearFavourites } = useFavourites();

  useEffect(() => {
    // Load properties from JSON file
    const loadProperties = async () => {
      try {
        const response = await fetch('/properties.json');
        const data = await response.json();
        setProperties(data.properties);
        setFilteredProperties(data.properties);
      } catch (error) {
        console.error('Error loading properties:', error);
        // Fallback to sample data if JSON fails to load
        const sampleProperties = [
          {
            id: 'prop1',
            type: 'House',
            bedrooms: 3,
            price: 750000,
            tenure: 'Freehold',
            description: 'Attractive three bedroom semi-detached family home',
            location: 'Petts Wood Road, Petts Wood, Orpington BR5',
            postcode: 'BR5',
            picture: '/images/prop1pic1.jpg',
            gallery: ['/images/prop1pic1.jpg', '/images/prop1pic2.jpg'],
            floorPlan: '/images/floorplan1.jpg',
            coordinates: { lat: 51.3886, lng: 0.0749 },
            added: { month: 'October', day: 12, year: 2022 }
          }
        ];
        setProperties(sampleProperties);
        setFilteredProperties(sampleProperties);
      }
    };

    loadProperties();
  }, []);

  const handleSearch = (criteria) => {
    setSearchCriteria(criteria);
    
    let filtered = properties;
    
    if (criteria.type && criteria.type !== 'any') {
      filtered = filtered.filter(prop => prop.type === criteria.type);
    }
    
    if (criteria.minPrice) {
      filtered = filtered.filter(prop => prop.price >= criteria.minPrice);
    }
    
    if (criteria.maxPrice) {
      filtered = filtered.filter(prop => prop.price <= criteria.maxPrice);
    }
    
    if (criteria.minBedrooms) {
      filtered = filtered.filter(prop => prop.bedrooms >= criteria.minBedrooms);
    }
    
    if (criteria.maxBedrooms) {
      filtered = filtered.filter(prop => prop.bedrooms <= criteria.maxBedrooms);
    }
    
    if (criteria.postcode) {
      filtered = filtered.filter(prop => prop.postcode === criteria.postcode);
    }
    
    if (criteria.startDate) {
      const startDate = new Date(criteria.startDate);
      filtered = filtered.filter(prop => {
        const propDate = new Date(prop.added.year, getMonthIndex(prop.added.month), prop.added.day);
        return propDate >= startDate;
      });
    }
    
    if (criteria.endDate) {
      const endDate = new Date(criteria.endDate);
      filtered = filtered.filter(prop => {
        const propDate = new Date(prop.added.year, getMonthIndex(prop.added.month), prop.added.day);
        return propDate <= endDate;
      });
    }
    
    setFilteredProperties(filtered);
  };

  const getMonthIndex = (month) => {
    const months = ['January', 'February', 'March', 'April', 'May', 'June', 
                   'July', 'August', 'September', 'October', 'November', 'December'];
    return months.indexOf(month);
  };

  const resetSearch = () => {
    setFilteredProperties(properties);
    setSearchCriteria({});
  };

  return (
    <Router>
      <div className="app">
        <Header />
        <main className="main-content">
          <Routes>
            <Route path="/" element={
              <div className="search-page">
                <div className="search-container">
                  <SearchForm 
                    onSearch={handleSearch} 
                    onReset={resetSearch}
                    properties={properties}
                  />
                  <div className="results-favourites-container">
                    <div className="results-section">
                      <h2>Properties ({filteredProperties.length})</h2>
                      <PropertyList 
                        properties={filteredProperties} 
                        favourites={favourites}
                        onToggleFavourite={addFavourite}
                      />
                    </div>
                    <div className="favourites-section">
                      <FavouritesList 
                        favourites={favourites}
                        properties={properties}
                        onRemoveFavourite={removeFavourite}
                        onClearFavourites={clearFavourites}
                      />
                    </div>
                  </div>
                </div>
              </div>
            } />
            <Route path="/property/:id" element={
              <PropertyDetail 
                properties={properties}
                favourites={favourites}
                onToggleFavourite={addFavourite}
              />
            } />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
